using FiberRoute.App;
using FiberRoute.Core;
using System.Reflection;
static class R142UiChecks
{
    const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.NonPublic;
    public static async Task Run(MainForm form,Store store,string output,Action<bool,string> check,Func<int,Task> idle,Action<string> shot)
    {
        T Field<T>(string name)=>(T)typeof(MainForm).GetField(name,Hidden)!.GetValue(form)!;
        void Set(string name,object value)=>typeof(MainForm).GetField(name,Hidden)!.SetValue(form,value);
        object? Call(string name,params object[] values)=>typeof(MainForm).GetMethod(name,Hidden)!.Invoke(form,values);
        IEnumerable<Control> Walk(Control parent){yield return parent;foreach(Control child in parent.Controls)foreach(var c in Walk(child))yield return c;}
        async Task Settle(){await idle(300);for(int i=0;i<200&&Field<bool>("busy");i++)await idle(50);}
        var tabs=Field<TabControl>("tabs");tabs.SelectedIndex=0;
        var graph=new Graph([new(0,"综合楼机房/ODF20","机房",true),new(1,"综合楼机房/ODF12","机房",true),new(2,"后宅机房/ODF06","机房",true),new(3,"后宅机房/ODF01","机房",true)],[new(0,"test","",1,2,2391.53,136,144,"")],"sequence-test");
        var route=new Route([0,3],[0],2391.53,0,0,136){Steps=[new(0,1,2)],Transfers=[new(0,1,0),new(2,3,1)]};
        var options=new RouteOptions(0,3,10,8,8,RouteOrder.Distance,[],[]);Set("routeGraph",graph);Set("routeOptions",options);Set("routes",new List<Route>{route,new([0,3],[],0,0,0,0)});Call("UpdateRouteSummary",new RouteResult(Field<List<Route>>("routes"),false,false,0,0));await Settle();
        var picker=Field<NodePicker>("start");var pickerInput=(TextBox)typeof(NodePicker).GetField("input",Hidden)!.GetValue(picker)!;check(pickerInput.Height>=pickerInput.Font.Height&&Math.Abs(pickerInput.Top-(picker.ClientSize.Height-pickerInput.Height)/2)<=2&&pickerInput.Bottom<=picker.ClientSize.Height,"R1.4.2 endpoint picker text is vertically centered without clipping");
        var number=Field<NumericUpDown>("demand");check(number.Height>=number.Font.Height&&Math.Abs(number.Top-(number.Parent!.ClientSize.Height-number.Height)/2)<=2&&number.Bottom<=number.Parent.ClientSize.Height,"R1.4.2 query numeric input is centered and fits its frame");
        var text=Field<TextBox>("routeSequence");var copy=Field<Button>("copyRoute");string expected=string.Join(" → ",ExportPlan.FromRoute(graph,route,options,1).Sequence);
        check(text.ReadOnly&&text.Multiline&&text.WordWrap&&text.Text==expected&&text.Text.Contains("ODF12")&&text.Width>text.Parent!.Width*0.8&&text.Height>=35*form.DeviceDpi/96&&text.Top>=30*form.DeviceDpi/96,"R1.4.2 visible route sequence includes actual internal endpoints and matches the workbook");copy.PerformClick();check(Clipboard.GetText()==expected,"R1.4.2 copy button copies the complete selected plan without truncating names");shot("R1.4.2-路由与复制");Field<ComboBox>("schemeChoice").SelectedIndex=1;await Settle();check(text.Text=="综合楼机房/ODF20 → 后宅机房/ODF01","R1.4.2 switching plans updates the sequence, including an internal-only route");Call("ClearRoutes");check(text.Text.Length==0&&!copy.Enabled,"R1.4.2 clearing results also clears stale copyable route text");
        tabs.SelectedIndex=1;await Settle();var search=Field<TextBox>("resourceSearch");var strip=search.Parent!.Parent!;check(strip.Controls.Cast<Control>().All(c=>c.Top==strip.Controls[0].Top&&c.Right<=strip.ClientSize.Width),"R1.4.2 resource filters and export stay on one row at the normal window size");check(Walk(strip).OfType<Button>().Any(b=>b.Text=="导出结果")&&!Walk(strip).OfType<Button>().Any(b=>b.Text=="导出筛选结果"),"R1.4.2 resource export uses the shortened caption");int before=search.Parent!.Width;form.Width+=120*form.DeviceDpi/96;await Settle();check(search.Parent.Width>before,"R1.4.2 resource search consumes extra horizontal space");form.Width-=120*form.DeviceDpi/96;await Settle();shot("R1.4.2-资源顺序与筛选");
        var nodes=store.Graph.Nodes;var cluster=new ClusterRecord("r142-members","潮南区威豹实业FG/GJ01-完整名称复核","光交箱",[nodes[0].Name,nodes[1].Name],"集群表来源","已确认","",false);store.SaveClusters([cluster]);Set("clusterState","全部");Field<ComboBox>("clusterTypeFilter").SelectedIndex=0;Field<ComboBox>("clusterRouteFilter").SelectedIndex=0;Field<TextBox>("clusterSearch").Text="r142-absent";tabs.SelectedIndex=2;Field<TabControl>("maintenanceTabs").SelectedIndex=1;Field<TextBox>("clusterSearch").Text="威豹实业";Call("LoadClusters");await Settle();var grid=Field<DataGridView>("clusterGrid");check(grid.Rows.Count==1&&(string)grid.Rows[0].Cells["成员名单"].Value==string.Join("；",cluster.Members.Order(StringComparer.Ordinal)),"R1.4.2 cluster table exposes the full member list and identity");check(!Walk(grid.Parent!).OfType<Label>().Any(l=>l.Text=="成员详情与来源"),"R1.4.2 cluster workspace no longer reserves the bottom details panel");check(grid.Columns["成员名单"].Width>grid.Columns["成员数"].Width*3&&grid.Rows[0].Height>=grid.Font.Height*2,"R1.4.2 compact cluster metadata leaves room and row height for complete names");shot("R1.4.2-集群成员名单");
        Field<TabControl>("maintenanceTabs").SelectedIndex=0;await Settle();var input=Field<TextBox>("typeSearch");check(input.Height>=input.Font.Height&&Math.Abs(input.Top-(input.Parent!.ClientSize.Height-input.Height)/2)<=2&&input.Bottom<=input.Parent.ClientSize.Height,"R1.4.2 node search text is centered with its full font height inside the frame");shot("R1.4.2-节点输入框");tabs.SelectedIndex=3;await Settle();var path=Field<TextBox>("importPath");check(path.ReadOnly&&path.BackColor==Color.White&&path.Height>=path.Font.Height&&path.Bottom<=path.Parent!.ClientSize.Height,"R1.4.2 readonly import path has the white input background and no clipped text");shot("R1.4.2-导入路径底色");
    }
}
